#include <stdio.h>

int add(int a, int b) {
    return a + b;
}

int sub(int a, int b) {
    return a - b;
}

int main() {
    // 1. Declare function pointer
    int (*op)(int, int);

    // 2. Assign function address
    op = add;
    printf("add: %d\n", op(10, 20));

    // 3. Reassign to another function
    op = sub;
    printf("sub: %d\n", op(10, 20));

    return 0;
}
